import 'package:flutter/material.dart';
import '../services/agent_service.dart';
import '../theme/pro_theme.dart';
import '../widgets/pro_app_bar.dart';
class ProAgentFleet extends StatefulWidget { const ProAgentFleet({super.key}); @override State<ProAgentFleet> createState()=>_ProAgentFleetState(); }
class _ProAgentFleetState extends State<ProAgentFleet>{
 final _agent=AgentService.instance; Future<List<Map<String,dynamic>>>? _future;
 @override void initState(){super.initState();_load();}
 void _load(){_future=_agent.subagentsForConversation('global');}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:ProTheme.bgDark,appBar:const ProAppBar(title:'Agent Fleet Overview'),body:Container(decoration:const BoxDecoration(gradient:ProTheme.bgGradient),child:FutureBuilder<List<Map<String,dynamic>>>(future:_future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString()));final agents=s.data??[];if(agents.isEmpty)return const Center(child:Padding(padding:EdgeInsets.all(28),child:Text('No persisted subagent activity yet. Delegated agents appear here when work is recorded.',textAlign:TextAlign.center,style:TextStyle(color:ProTheme.textSecondary))));return RefreshIndicator(onRefresh:()async{setState(_load);await _future;},child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:agents.length,itemBuilder:(c,i){final a=agents[i];final id=a['task_id']?.toString()??a['id']?.toString()??'';final status=a['status']?.toString()??'unknown';return Card(color:ProTheme.bgCard,child:ListTile(leading:const Icon(Icons.smart_toy,color:ProTheme.neonGreen),title:Text(a['title']?.toString()??a['agent_id']?.toString()??'Subagent',style:const TextStyle(color:ProTheme.textPrimary)),subtitle:Text('$status • $id',style:const TextStyle(color:ProTheme.textSecondary,fontSize:11)),trailing:PopupMenuButton<String>(onSelected:(v)async{try{if(v=='cancel')await _agent.cancelSubagent(id);if(v=='dismiss')await _agent.dismissSubagent(id);if(mounted)setState(_load);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},itemBuilder:(_)=>const[PopupMenuItem(value:'cancel',child:Text('Cancel')),PopupMenuItem(value:'dismiss',child:Text('Dismiss'))])));}));} })));
}
